#!/usr/bin/env python3
"""Materialize four source-inspected R0 pilot reductions deterministically."""
from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "programs" / "v2-intakes" / "pilot-reductions"
BOUNDARY = "Review-only source reduction; no gap, novelty, prevalence, proposal, or lifecycle transition is established."


def stable(path: Path, body: dict) -> None:
    encoded = json.dumps(body, ensure_ascii=False, indent=2) + "\n"
    if path.exists() and json.loads(path.read_text(encoding="utf-8")) != body:
        raise ValueError(f"refusing to overwrite divergent reduction: {path}")
    if path.exists():
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(encoded, encoding="utf-8")


def pdf(source_id: str, title: str, url: str, pdf_url: str, digest: str, spans: list[tuple[str, str]], supports: str, does_not: str, kind: str = "PRIMARY_PAPER", identity: str = "EXACT_TITLE_AND_SOURCE_ID_CONFIRMED") -> dict:
    return {
        "source_id": source_id, "title": title, "url": url, "pdf_url": pdf_url, "kind": kind,
        "source_function": "SCIENTIFIC_FRONTIER", "content_form": "PDF", "fulltext_state": "FULLTEXT_INSPECTED",
        "content_digest": f"sha256:{digest}", "local_cache_state": "REPO_RUNTIME_CACHE_NOT_ZOTERO_ATTACHMENT",
        "local_cache_path": f".runtime/source-inspection-remaining/{source_id}.pdf",
        "zotero_attachment_state": "NOT_ATTACHED", "zotero_snapshot_state": "NOT_CAPTURED",
        "identity_review": identity,
        "inspection_spans": [{"locator": locator, "observation": observation} for locator, observation in spans],
        "supports": supports, "does_not_establish": does_not,
    }


def html(source_id: str, title: str, url: str, spans: list[tuple[str, str]], supports: str, does_not: str, observed_at: str = "2026-07-19") -> dict:
    return {
        "source_id": source_id, "title": title, "url": url, "kind": "PRIMARY_WORKFLOW_HTML",
        "source_function": "PRIMARY_WORKFLOW", "content_form": "HTML", "fulltext_state": "FULLTEXT_INSPECTED",
        "content_digest": "NOT_RECORDED_DYNAMIC_HTML", "local_cache_state": "NOT_CACHED",
        "zotero_attachment_state": "NOT_ATTACHED", "zotero_snapshot_state": "NOT_CAPTURED",
        "observed_at": observed_at,
        "inspection_spans": [{"locator": locator, "observation": observation} for locator, observation in spans],
        "supports": supports, "does_not_establish": does_not,
    }


def packet(program: str, packet_id: str, sources: list[dict]) -> dict:
    return {
        "artifact_type": "source-inspection-packet", "schema_version": "1.0", "packet_id": packet_id,
        "program_key": program, "created_at": "2026-07-19T00:00:00+08:00",
        "review_status": "REVIEW_ONLY_NOT_A_GATE_VERDICT", "sources": sources,
        "controller_boundary": "Inspection repairs source identity and locator gaps only. Repository cache, Zotero attachment, and Zotero snapshot remain separate states. " + BOUNDARY,
    }


def no_signal(program: str, decision_id: str, source_ids: list[str], reason: str) -> dict:
    return {
        "artifact_type": "opportunity-decision", "schema_version": "1.0", "decision_id": decision_id,
        "program_key": program, "decision": "NO_ADMISSIBLE_SIGNAL", "searched_through": "2026-07-19",
        "reason": reason, "missing_source_function": "PRIMARY_WORKFLOW", "source_ids": source_ids,
        "next_legal_work": "Retain the literature-led draft problem case and seek an independent primary workflow or ecosystem signal; do not manufacture an opportunity map.",
        "does_not_establish": "No absence claim or research gap follows from this bounded search.",
        "controller_boundary": BOUNDARY,
    }


def problem(program: str, artifact_id: str, problem_id: str, question: str, owner: str, worlds: list[str], discriminator: str, falsifier: str, spans: list[dict], questions: list[dict]) -> dict:
    return {
        "artifact_type": "problem-case", "schema_version": "1.0", "artifact_id": artifact_id,
        "problem_id": problem_id, "program_key": program,
        "status": "DRAFT_R0_SOURCE_REDUCTION_PENDING_INDEPENDENT_REVIEW",
        "research_question": question, "decision_owner": owner, "worlds": worlds,
        "discriminator": discriminator, "falsifier": falsifier,
        "scope": "Method-free R0 problem framing; any benchmark, replay system, or visualization is an instrument.",
        "does_not_establish": BOUNDARY, "source_spans": spans, "derived_questions": questions,
        "controller_boundary": "Independent review is required before any route or promotion decision.",
    }


def span(source: dict, locator: str, observation: str, resolves: str, leaves: str, posture: str = "OBJECTIVELY_LEAVES") -> dict:
    return {
        "source_id": source["source_id"], "title": source["title"], "url": source["url"], "kind": source["kind"],
        "locator": locator, "observation": observation, "problem_posture": posture,
        "resolves": resolves, "leaves_unresolved": leaves, "does_not_establish": source["does_not_establish"],
    }


def opportunity(program: str, artifact_id: str, map_id: str, scope: str, sources: list[dict], cluster: dict) -> dict:
    normalized_sources = [
        {**source, "observed_at": source.get("observed_at") or "2026-07-19"}
        for source in sources
    ]
    return {
        "artifact_type": "opportunity-map", "schema_version": "1.0", "artifact_id": artifact_id,
        "map_id": map_id, "program_key": program, "scope": scope, "searched_through": "2026-07-19",
        "created_at": "2026-07-19T00:00:00+08:00", "valid_until": "2026-08-19",
        "review_status": "DRAFT_PENDING_INDEPENDENT_REVIEW",
        "does_not_establish": "A bounded inspiration artifact, not a research-gap, novelty, prevalence, or lifecycle certificate.",
        "sources": normalized_sources, "tension_clusters": [cluster],
        "controller_boundary": BOUNDARY,
    }


